// src/index.js
import './App.scss';
import './Button.scss';
import './Responsive1500.scss';
import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import { worker } from "./mocks/browser";

// MSW 먼저 준비시키고, 준비된 뒤에 React 렌더
(async function bootstrap() {
  await worker.start({
    serviceWorker: { url: "/mockServiceWorker.js"}, // 루트에 고정
    onUnhandledRequest: "bypass", // 안 잡히면 통과
  });
  console.log("[MSW] registered at /mockServiceWorker.js");
  const root = ReactDOM.createRoot(document.getElementById("root"));
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
})();


// 어떤 URL로 치는지 + 응답 상태를 즉시 확인
(async () => {
  const { apiPath } = await import("/woodenpages/static/js/src_api_config_js.chunk.js").catch(()=>({apiPath:(x)=>x}));
  const url = apiPath ? apiPath("/order/orderlist") : "/order/orderlist";
  console.log("REQ URL = ", url);
  try {
    const r = await fetch(url);
    console.log("STATUS = ", r.status, "  FINAL_URL = ", r.url);
  } catch (e) {
    console.log("FETCH ERROR = ", e.message);
  }
})();


function firstBase() {
  const vite = (typeof import.meta !== "undefined" && import.meta.env && import.meta.env.BASE_URL) || "";
  const cra  = (typeof process !== "undefined" && process.env && process.env.PUBLIC_URL) || "";
  const picked = cra || vite || "/";
  return picked.endsWith("/") ? picked : picked + "/";
}
function pathBase() {
  const p = (typeof window !== "undefined" && window.location && window.location.pathname) || "/";
  const seg = p.split("/").filter(Boolean)[0];
  return seg ? `/${seg}/` : "/";
}
